/* ================================================================
   GÉLULES EN MOUVEMENT (v116)

   Une gélule est un objet brillant et lourd. On ne l'anime pas pour
   l'animer :
     · quand on la fait glisser du doigt, elle TOURNE sur elle-même et
       la LUMIÈRE passe sur sa surface — le reflet suit le geste, et
       l'inclinaison du téléphone ;
     · elle TOMBE en place avec du poids à l'ouverture, se TASSE quand
       elle s'arrête ou qu'on la touche ;
     · la dernière S'OUVRE en deux pour laisser entrer dans l'application.
   Tout passe par transform et opacity : c'est le processeur graphique
   qui travaille, rien n'est repeint. Réduction des animations demandée
   par le téléphone : tout est coupé (voir la fin du bloc).
   ================================================================ */
.gelule-cadre{
  --base: 1.06;
  position: relative; display: block; width: 100%; height: 100%;
  transform: perspective(1100px) rotateY(var(--ry, 0deg)) rotateX(var(--rx, 0deg))
             scale(calc(var(--base) - var(--ad, 0) * 0.1));
  transition: scale .5s cubic-bezier(.3,1.6,.45,1);
  will-change: transform;
.gelule-cadre > img.gelule{ transform: none; }
.gelule-reflet{
  position: absolute; inset: 0; overflow: hidden; pointer-events: none;
  mix-blend-mode: soft-light;
  -webkit-mask-size: contain; mask-size: contain;
  -webkit-mask-position: center; mask-position: center;
  -webkit-mask-repeat: no-repeat; mask-repeat: no-repeat;
}
.slide:nth-child(1) .gelule-reflet{ -webkit-mask-image: url(assets/pills/1.webp); mask-image: url(assets/pills/1.webp); }
.slide:nth-child(2) .gelule-reflet{ -webkit-mask-image: url(assets/pills/2.webp); mask-image: url(assets/pills/2.webp); }
.slide:nth-child(3) .gelule-reflet{ -webkit-mask-image: url(assets/pills/3.webp); mask-image: url(assets/pills/3.webp); }
.gelule-reflet i{
  position: absolute; top: -25%; bottom: -25%; left: -55%; width: 55%;
  background: linear-gradient(100deg, transparent 8%, rgba(255,255,255,.9) 46%,
              rgba(255,255,255,.35) 56%, transparent 90%);
  transform: translateX(calc((var(--lum, 0) + 1) * 140%)) skewX(-14deg);
}
/* Elle tombe en place à l'ouverture… */
#onboard .slide:first-child .gelule-cadre{ animation: gelule-arrivee .95s cubic-bezier(.2,.75,.25,1) both; }
@keyframes gelule-arrivee{
  0%  { opacity: 0; translate: 0 80px; scale: .9 .82; }
  55% { opacity: 1; translate: 0 -10px; scale: 1.05 .96; }
  78% { translate: 0 4px; scale: .985 1.03; }
  100%{ translate: 0 0; scale: 1 1; }
}
/* …se tasse quand elle s'arrête sous le doigt… */
.gelule-cadre.posee{ animation: gelule-posee .55s cubic-bezier(.3,.7,.3,1); }
@keyframes gelule-posee{
  0%  { scale: 1 1; }
  35% { scale: 1.03 .965; }
  70% { scale: .99 1.015; }
  100%{ scale: 1 1; }
}
/* …et cède un peu quand on la touche. */
.slide.presse .gelule-cadre{ scale: .965; transition-duration: .12s; }

/* Le texte sort de la gélule au lieu d'apparaître en fondu. */
.consent-block{ clip-path: inset(22% 10% 22% 10% round 32px);
  transition: opacity .45s ease, transform .55s cubic-bezier(.2,.8,.2,1), clip-path .6s cubic-bezier(.2,.8,.2,1); }
.consent-block.show{ clip-path: inset(0 0 0 0 round 32px); }
/* Les encarts flottent légèrement à contre-courant du geste : profondeur. */
.slide .browser-notice, .slide .finale-notice{ translate: calc(var(--d, 0) * -22px) 0; }
/* Sur la pilule qui arrive, les lignes se posent une à une et les coches
   se dessinent : la confiance se lit, elle ne s'affiche pas d'un bloc. */
.install-carte .apk-tete, .install-carte .confiance li, .install-carte #installBtn{
  opacity: 0; translate: 0 12px; transition: opacity .45s ease, translate .6s cubic-bezier(.2,.8,.2,1); }
.slide.actif .install-carte .apk-tete,
.slide.actif .install-carte .confiance li,
.slide.actif .install-carte #installBtn{ opacity: 1; translate: 0 0; }
.slide.actif .install-carte .confiance li:nth-child(1){ transition-delay: .12s; }
.slide.actif .install-carte .confiance li:nth-child(2){ transition-delay: .22s; }
.slide.actif .install-carte .confiance li:nth-child(3){ transition-delay: .32s; }
.slide.actif .install-carte #installBtn{ transition-delay: .42s; }
.confiance svg path{ stroke-dasharray: 22; stroke-dashoffset: 22; transition: stroke-dashoffset .5s cubic-bezier(.6,0,.2,1); }
.slide.actif .confiance li:nth-child(1) svg path{ stroke-dashoffset: 0; transition-delay: .35s; }
.slide.actif .confiance li:nth-child(2) svg path{ stroke-dashoffset: 0; transition-delay: .45s; }
.slide.actif .confiance li:nth-child(3) svg path{ stroke-dashoffset: 0; transition-delay: .55s; }

/* La dernière gélule s'ouvre en deux : c'est la porte de l'application. */
#onboard.ouverte .finale-notice, #onboard.ouverte .finale-logo{ opacity: 0; transition: opacity .2s ease; }
.gelule-ouverture{ position: fixed; inset: 0; z-index: 120; pointer-events: none; }
.gelule-ouverture .moitie{ position: fixed; }
.gelule-ouverture .moitie img{ width: 100%; height: 100%; object-fit: contain; display: block; }
.gelule-ouverture .haut{ clip-path: inset(0 0 50% 0); }
.gelule-ouverture .bas { clip-path: inset(50% 0 0 0); }
.gelule-ouverture.go .haut{ animation: moitie-haut 1s cubic-bezier(.6,0,.3,1) forwards; }
.gelule-ouverture.go .bas { animation: moitie-bas 1s cubic-bezier(.6,0,.3,1) forwards; }
@keyframes moitie-haut{
  0%  { transform: none; }
  16% { transform: translateY(6px) scaleX(1.025); }
  62% { opacity: 1; }
  100%{ transform: translateY(-58vh) rotate(-11deg); opacity: 0; }
}
@keyframes moitie-bas{
  0%  { transform: none; }
  16% { transform: translateY(-6px) scaleX(1.025); }
  62% { opacity: 1; }
  100%{ transform: translateY(58vh) rotate(8deg); opacity: 0; }
}
.gelule-ouverture .jointure{
  position: fixed; height: 3px; margin-top: -1.5px; opacity: 0;
  background: radial-gradient(closest-side, #f2fff8, rgba(62,224,140,.95) 45%, rgba(62,224,140,0));
}
.gelule-ouverture.go .jointure{ animation: jointure 1s cubic-bezier(.3,0,.2,1) forwards; }
@keyframes jointure{
  0%  { transform: scale(0, 1); opacity: 0; }
  16% { transform: scale(.95, 1); opacity: 1; }
  100%{ transform: scale(1.5, 140); opacity: 0; }
}

@media (min-width: 900px){
  .gelule-cadre{ --base: 1; display: inline-block; width: auto; height: auto; }
