/* Déjà dans l'application ? Proposer de télécharger l'APK depuis l'APK
   n'aurait aucun sens. L'APK v2.2 ne marque PLUS son agent utilisateur
   (« SonoraAPK » le faisait trier comme robot par les régies) : on le
   reconnaît à son pont, window.SonoraNative, qu'aucun navigateur n'a.
   L'ancien marqueur reste accepté pour les APK v2.0 encore installés. */
const IS_APK = !!window.SonoraNative || /SonoraAPK/i.test(navigator.userAgent || "");
const IS_ANDROID = /Android/i.test(navigator.userAgent || "");

/* La carte d'installation n'a de sens que sur un téléphone Android, hors
   de l'application. Ailleurs, elle laisse la place à un conseil adapté.
   Posé DÈS le chargement : le bloc n'existe jamais à l'écran là où il
   n'a rien à faire, quel que soit le chemin emprunté. */
function adapterInstallation(){
  const bloc = document.getElementById('installBloc');
  const ailleurs = document.getElementById('installAilleurs');
  if(!bloc || !ailleurs) return;
  const android = IS_ANDROID && !IS_IOS && !IS_APK;
  bloc.hidden = !android;
  ailleurs.hidden = android;
  if(!android){
    document.getElementById('installAilleursTexte').textContent = IS_IOS
      ? "Sur iPhone, ajoute Sonora à ton écran d'accueil : bouton Partager de Safari, puis « Sur l'écran d'accueil »."
      : "L'application Android s'installe depuis ton téléphone : ouvre sonora-musique.vercel.app sur Android.";
  }
adapterInstallation();
document.addEventListener('DOMContentLoaded', adapterInstallation);
  adapterInstallation();
  }

  /* ---- Mouvement des gélules (voir « GÉLULES EN MOUVEMENT » dans le CSS) ----
     Un seul calcul par image, et seulement quand quelque chose bouge :
     le défilement ou l'inclinaison. Rien ne tourne à vide. */
  const slides = Array.from(document.querySelectorAll('.slide'));
  const calmes = !!(window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches);
  const incl = { x: 0, y: 0, cx: 0, cy: 0 };
  let rafMouvement = 0;
  function poserMouvement(){
    rafMouvement = 0;
    const w = carousel.clientWidth || 1, sx = carousel.scrollLeft;
    incl.x += (incl.cx - incl.x) * 0.14;
    incl.y += (incl.cy - incl.y) * 0.14;
    slides.forEach(s => {
      const d = Math.max(-1, Math.min(1, (s.offsetLeft - sx) / w));
      const ad = Math.abs(d), pres = 1 - ad;
      s.style.setProperty('--d', d.toFixed(3));
      s.style.setProperty('--ad', ad.toFixed(3));
      s.style.setProperty('--ry', (calmes ? 0 : -d * 26 + incl.x * 6 * pres).toFixed(2) + 'deg');
      s.style.setProperty('--rx', (calmes ? 0 : -incl.y * 4 * pres).toFixed(2) + 'deg');
      s.style.setProperty('--lum', (d * 1.15 + incl.x * 0.55).toFixed(3));
    });
    if(Math.abs(incl.cx - incl.x) > 0.003 || Math.abs(incl.cy - incl.y) > 0.003) demanderMouvement();
  }
  function demanderMouvement(){ if(!rafMouvement) rafMouvement = requestAnimationFrame(poserMouvement); }
  /* Inclinaison : Android la donne sans autorisation ; iOS en exige une,
     qu'on ne demande pas pour un simple reflet. */
  function surInclinaison(e){
    if(e.gamma == null) return;
    incl.cx = Math.max(-1, Math.min(1, e.gamma / 22));
    incl.cy = Math.max(-1, Math.min(1, ((e.beta || 0) - 40) / 22));
    demanderMouvement();
  }
  const avecInclinaison = !calmes && 'DeviceOrientationEvent' in window
                          && typeof DeviceOrientationEvent.requestPermission !== 'function';
  if(avecInclinaison) addEventListener('deviceorientation', surInclinaison);
  function arreterMouvement(){
    if(avecInclinaison) removeEventListener('deviceorientation', surInclinaison);
    cancelAnimationFrame(rafMouvement); rafMouvement = 0;
  }
  carousel.addEventListener('scroll', demanderMouvement, { passive: true });
  demanderMouvement();
  slides[0].classList.add('actif');
  function tasser(cadre){
    if(calmes || !cadre) return;
    cadre.classList.remove('posee'); void cadre.offsetWidth; cadre.classList.add('posee');
  }
  slides.forEach(s => {
    const c = s.querySelector('.gelule-cadre');
    if(c) c.addEventListener('animationend', () => c.classList.remove('posee'));
    s.addEventListener('pointerdown', e => { if(!e.target.closest('button,a')) s.classList.add('presse'); });
    ['pointerup', 'pointercancel', 'pointerleave'].forEach(t => s.addEventListener(t, () => s.classList.remove('presse')));
  });

  /* La gélule s'ouvre : deux moitiés de la même image qui se séparent,
     une lumière à la jointure. Rien à télécharger de plus. */
  function ouvrirGelule(cadre){
    const img = cadre && cadre.querySelector('img');
