      m.className = 'moitie ' + cote;
      m.style.cssText = 'left:' + r.left + 'px;top:' + r.top + 'px;width:' + r.width + 'px;height:' + r.height + 'px';
      const copie = document.createElement('img');
      copie.src = img.src; copie.alt = '';
      m.appendChild(copie);
      scene.appendChild(m);
    });
    const jointure = document.createElement('div');
    jointure.className = 'jointure';
    jointure.style.cssText = 'left:' + (r.left + r.width * 0.1) + 'px;width:' + (r.width * 0.8) + 'px;top:' + (r.top + r.height / 2) + 'px';
    scene.appendChild(jointure);
    document.body.appendChild(scene);
    document.getElementById('onboard').classList.add('ouverte');
    cadre.style.visibility = 'hidden';
    requestAnimationFrame(() => scene.classList.add('go'));
        slides.forEach((s, i) => s.classList.toggle('actif', i === newIndex));
