/* Plafond du cache des pochettes : au-delà, les plus anciennes partent.
   Sans lui, chaque pochette vue une seule fois restait pour toujours dans
   le téléphone, et le stockage de l'application grossissait sans fin. */
const MEDIA_MAX = 500;
let mediaRangement = 0;
function rangerMedia(cache){
  if(++mediaRangement % 25) return;   // un contrôle toutes les 25 mises en cache
  cache.keys().then(cles => {
    const trop = cles.length - MEDIA_MAX;
    for(let i = 0; i < trop; i++) cache.delete(cles[i]);
  }).catch(() => {});
}
